mut_method_definition:
public int elementCompareTo(final T element) {
        // Comparable API says throw NPE on null
        Validate.notNull(element, "element");
        if (isAfter(element)) {
            return -1;
        } else if (isBefore(element)) {
            return 1;
        } else {
            return 0;
        }
    }

