public T fit(final T element) {
        // Comparable API says throw NPE on null
        Validate.notNull(element, "element");
        if (isAfter(element)) {
            return minimum;
        } else if (isBefore(element)) {
            return maximum;
        } else {
            return element;
        }
    }

