mut_method_definition:
public static boolean[] insert(final int index, final boolean[] array, final boolean... values) {
        if (array == null) {
            return null;
        }
        if (ArrayUtils.isEmpty(values)) {
            return clone(array);
        }
        if (index < 0 || index > array.length) {
